      channel.sendMessage([urlArg] as [Any?]) { response in
        guard let listResponse = response as? [Any?] else {
          continuation.resume(throwing: createConnectionError(withChannelName: channelName))
          return
        }
        if listResponse.count > 1 {
          let code: String = listResponse[0] as! String
          let message: String? = nilOrValue(listResponse[1])
          let details: String? = nilOrValue(listResponse[2])
          continuation.resume(throwing: BridgeError(code: code, message: message, details: details))
        } else if MessagesPigeonInternal.isNullish(listResponse[0]) {
          continuation.resume(throwing: BridgeError(code: "null-error", message: "Flutter api returned null value for non-null return value.", details: ""))
        } else {
          let result = listResponse[0] as! Bool
          continuation.resume(returning: result)
